import { Reference } from '@ethersphere/core-sdk';
import { Optional } from 'cafe-utility';
import { UploadResultBody } from "../types/schema/upload.js";
import { prepareRequestHeaders } from "../utils/headers.js";
import { http } from "../utils/http.js";
import { makeTagUid } from "../utils/type.js";
const socEndpoint = 'soc';
/**
 * Raw HTTP calls for the `/soc` endpoint.
 */
export async function upload(requestOptions, owner, identifier, signature, data, stamp, options) {
  const response = await http(requestOptions, {
    method: 'post',
    url: `${socEndpoint}/${owner}/${identifier}`,
    data,
    headers: {
      'content-type': 'application/octet-stream',
      ...prepareRequestHeaders(stamp, options)
    },
    responseType: 'json',
    params: {
      sig: signature.toHex()
    }
  });
  const body = UploadResultBody.parse(response.data);
  return {
    reference: body.reference,
    tagUid: response.headers['swarm-tag'] ? makeTagUid(response.headers['swarm-tag']) : undefined,
    historyAddress: response.headers['swarm-act-history-address'] ? Optional.of(new Reference(response.headers['swarm-act-history-address'])) : Optional.empty()
  };
}